<script>
(() => {
 const modal=document.getElementById('cfmoney-modal');if(!modal)return;
 const form=modal.querySelector('form'),field=n=>form.elements.namedItem(n),money=n=>'৳'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 let info=null,type='',url='',token='',busy=false,previousFocus=null;
 const error=message=>{const el=modal.querySelector('#cfmoney-error');el.textContent=message;el.hidden=!message};
 const uuid=()=>{const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`};
 const target=()=>info.targets.find(t=>String(t.id)===field('service_cost_id').value);
 function calculation(){const cost=type==='refund'?Number(target()?.cost||0):Number(field('amount').value||0),refund=type==='refund'?Number(field('vendor_refund').value||0):0,penalty=type==='refund'?Math.max(0,cost-refund):0,clientRefund=type==='refund'?0:0,delta=(field('bearer').value==='client'?(type==='refund'?penalty:cost):0)-clientRefund;return {cost,refund,penalty,clientRefund,delta,charge:Number(info.charge)+delta,newCost:Number(info.cost)+(type==='refund'?-refund:cost)}}
 function preview(){if(!info)return;const c=calculation();modal.querySelector('#cfmoney-oldcost').value=money(c.cost);modal.querySelector('#cfmoney-penalty').value=money(c.penalty);const box=modal.querySelector('#cfmoney-preview');box.replaceChildren();[['Charge',info.charge,c.charge],['Cost',info.cost,c.newCost],['Profit',Number(info.charge)-Number(info.cost),c.charge-c.newCost]].forEach(([label,before,after])=>{const el=document.createElement('div');el.className='cfmoney-preview-metric';const caption=document.createElement('small');caption.textContent=label;const value=document.createElement('strong');value.textContent=money(after);if(after<0)value.style.color='#dc354e';const previous=document.createElement('span');previous.textContent='Was '+money(before);el.append(caption,value,previous);box.append(el)});const note=document.createElement('p');note.className='cfmoney-preview-note';note.textContent=!field('bearer').value?'Choose who bears the cost to complete the preview.':type==='refund'?'Client refund credit '+money(Math.max(0,Number(info.paid)-c.charge))+' · Provider refund credit '+money(Math.max(0,Number(target()?.paid||0)-(c.cost-c.refund))):'Independent service cost; original charges and payments remain in history.';box.append(note)}
 function review(on){modal.querySelector('#cfmoney-inputs').hidden=on;modal.querySelector('#cfmoney-review').hidden=!on;modal.querySelector('#cfmoney-review-button').hidden=on;modal.querySelector('#cfmoney-confirm').hidden=!on;modal.querySelector('#cfmoney-back').hidden=!on;error('')}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-cf-money]');if(!button||busy)return;const root=button.closest('[data-cf-money-info]');if(!root)return;info=JSON.parse(root.dataset.cfMoneyInfo);type=button.dataset.cfMoney;url=root.dataset.cfMoneyUrl;token=uuid();previousFocus=button;form.reset();modal.querySelector('#cfmoney-title').textContent=({refund:'Refund',reprocess:'Re-process / Re-submit',others:'Other Service'}[type]+' '+info.number);modal.querySelector('#cfmoney-person').textContent=info.name;modal.querySelector('[data-cfm-refund]').hidden=type!=='refund';modal.querySelector('[data-cfm-service]').hidden=type==='refund';for(const input of modal.querySelectorAll('[data-cfm-refund] input,[data-cfm-refund] select'))input.disabled=type!=='refund';for(const input of modal.querySelectorAll('[data-cfm-service] input,[data-cfm-service] select'))input.disabled=type==='refund';field('vendor_refund').required=type==='refund';field('title').required=type!=='refund';field('vendor_id').required=type!=='refund';field('amount').required=type!=='refund';field('vendor_id').value=info.vendor_id||'';field('title').value=type==='reprocess'?'Re-processing':'';const select=field('service_cost_id');select.replaceChildren();info.targets.forEach(t=>{const o=document.createElement('option');o.value=t.id;o.textContent=`${t.title} · ${t.vendor||'Unassigned'} · ${money(t.cost)}${t.refunded?' · Already refunded':''}`;o.disabled=t.refunded;select.append(o)});const available=Array.from(select.options).find(o=>!o.disabled);if(available)select.value=available.value;else select.selectedIndex=-1;review(false);preview();modal.hidden=false;field(type==='refund'?'service_cost_id':'title').focus()},true);
 form.addEventListener('input',preview);form.addEventListener('change',preview);
 form.addEventListener('submit',event=>{event.preventDefault();if(busy||!form.reportValidity())return;const c=calculation();if(type==='refund' && (!target()||c.refund>c.cost||c.clientRefund>info.charge)){error('Select an unrefunded cost. Vendor refund cannot exceed the selected cost.');return}if(type!=='refund' && (Number(field('paid_amount').value)>c.cost || (Number(field('paid_amount').value)>0 && (!field('bank_id').value||!field('payment_date').value)))){error('Payment must not exceed cost and requires bank and payment date.');return}modal.querySelector('#cfmoney-review-text').textContent=type==='refund'?`Vendor payable reduced by ${money(c.refund)}.\nPackage charge is preserved.\nRetained penalty ${money(c.penalty)} — ${field('bearer').value==='client'?'billed to Agent / Client':'Company bears; remains in cost'}.\nOne net client adjustment: ${money(c.delta)}.\nNo bank/cash movement.`:`New vendor payable ${money(c.cost)}.\n${field('bearer').value==='client'?`Agent / Client charge increases by ${money(c.cost)}.`:'Package charge unchanged; Company bears cost.'}\nVendor payment now: ${money(field('paid_amount').value)}.\nService: ${field('title').value}`;review(true)});
 modal.querySelector('#cfmoney-back').addEventListener('click',()=>{if(!busy)review(false)});
 modal.querySelectorAll('[data-cfm-close]').forEach(button=>button.addEventListener('click',()=>{if(busy)return;modal.hidden=true;previousFocus?.focus()}));
 modal.querySelector('#cfmoney-confirm').addEventListener('click',async()=>{if(busy)return;busy=true;const button=modal.querySelector('#cfmoney-confirm');button.disabled=true;button.textContent='Posting…';const payload=Object.fromEntries(new FormData(form));payload.type=type;payload.request_token=token;for(const key of Object.keys(payload))if(payload[key]==='')delete payload[key];try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Posting failed.');location.reload()}catch(e){error(e.message);busy=false;button.disabled=false;button.textContent='Confirm & post'}});
 modal.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=Array.from(modal.querySelectorAll('button,input,select')).filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
})();
</script>
